import fs from 'node:fs/promises';
import {createServer} from 'node:http';
import {chromium} from '/Users/blamy/.codex/worktrees/mips-throughput/wasm-vm/web/node_modules/playwright/index.mjs';
const html='<!doctype html><canvas width=16 height=16></canvas>';
const server=createServer((req,res)=>res.end(html));await new Promise(r=>server.listen(0,'127.0.0.1',r));
const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:false,args:['--enable-gpu']});
try{
const page=await browser.newPage();await page.goto('http://127.0.0.1:'+server.address().port+'/');await page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));
const report=await page.evaluate(async()=>{
const gl=document.querySelector('canvas').getContext('webgl2',{antialias:false,preserveDrawingBuffer:true,failIfMajorPerformanceCaveat:true});
const ext=gl.getExtension('WEBGL_provoking_vertex'),debug=gl.getExtension('WEBGL_debug_renderer_info');
const shader=(type,text)=>{const s=gl.createShader(type);gl.shaderSource(s,text);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;};
const vertex='#version 300 es\nin vec2 a;flat out uvec4 id;void main(){gl_Position=vec4(a,0,1);id=floatBitsToUint(vec4(float(gl_VertexID+1)/256.,0.25,0.5,1.));}',fragment='#version 300 es\nprecision highp float;flat in uvec4 id;out vec4 c;void main(){c=uintBitsToFloat(id);}';
const p=gl.createProgram();gl.attachShader(p,shader(gl.VERTEX_SHADER,vertex));gl.attachShader(p,shader(gl.FRAGMENT_SHADER,fragment));gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(p));gl.useProgram(p);
const vertices=new Float32Array(104*2),ids=[3,19,61,103],coords=[[2.5,2.5],[6.5,2.5],[6.5,6.5],[2.5,6.5]];for(let n=0;n<4;n++)vertices.set(coords[n].map(x=>x/8-1),ids[n]*2);
const a=gl.createBuffer(),i=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,a);gl.bufferData(gl.ARRAY_BUFFER,vertices,gl.STATIC_DRAW);const slot=gl.getAttribLocation(p,'a');gl.vertexAttribPointer(slot,2,gl.FLOAT,false,8,0);gl.enableVertexAttribArray(slot);gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,i);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,new Uint16Array(ids),gl.STATIC_DRAW);
const fb=gl.createFramebuffer(),texture=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,texture);gl.texStorage2D(gl.TEXTURE_2D,1,gl.RGBA8,16,16);gl.bindFramebuffer(gl.FRAMEBUFFER,fb);gl.framebufferTexture2D(gl.FRAMEBUFFER,gl.COLOR_ATTACHMENT0,gl.TEXTURE_2D,texture,0);gl.drawBuffers([gl.COLOR_ATTACHMENT0]);gl.readBuffer(gl.COLOR_ATTACHMENT0);gl.viewport(0,0,16,16);
const cases=[];for(const convention of ['default',...(ext?['last','first','last-restored']:[])]){
if(convention!=='default')ext.provokingVertexWEBGL(convention==='first'?ext.FIRST_VERTEX_CONVENTION_WEBGL:ext.LAST_VERTEX_CONVENTION_WEBGL);
for(const mode of [gl.LINES,gl.LINE_LOOP,gl.LINE_STRIP,gl.TRIANGLES,gl.TRIANGLE_STRIP,gl.TRIANGLE_FAN]){
gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);gl.drawElements(mode,4,gl.UNSIGNED_SHORT,0);const sync=gl.fenceSync(gl.SYNC_GPU_COMMANDS_COMPLETE,0);gl.flush();while(gl.clientWaitSync(sync,0,0)===gl.TIMEOUT_EXPIRED)await new Promise(r=>setTimeout(r,1));gl.deleteSync(sync);const pixels=new Uint8Array(1024);gl.readPixels(0,0,16,16,gl.RGBA,gl.UNSIGNED_BYTE,pixels);const sample=([x,y])=>[...pixels.slice((y*16+x)*4,(y*16+x)*4+4)];cases.push({convention,mode,provoking:ext?gl.getParameter(ext.PROVOKING_VERTEX_WEBGL):null,samples:[[4,2],[6,4],[4,6],[2,4],[4,4]].map(sample),pixels:[...pixels],error:gl.getError()});
}}
return {planningOnly:true,gpu:debug?gl.getParameter(debug.UNMASKED_RENDERER_WEBGL):gl.getParameter(gl.RENDERER),extension:Boolean(ext),extensions:gl.getSupportedExtensions(),vertex,fragment,ids,vertices:[...vertices],width:16,height:16,cases};
});await fs.writeFile('/tmp/wasmvm-provoking-word-probe.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({gpu:report.gpu,extension:report.extension,cases:report.cases.map(({pixels,...rest})=>rest)}));
}finally{await browser.close();await new Promise(r=>server.close(r));}
